from scipy.spatial import distance


def total_travel_distance(points):
    """
    Calculate the total travel distance of a closed round trip.

    The path starts at the first point, visits each consecutive point in
    order, and finally returns to the starting point.

    Parameters
    ----------
    points : list
        A list of 2D coordinates. Each coordinate is normally a tuple/list
        of two numbers (x, y). If a coordinate tuple contains just one
        number, both coordinates are assumed to be equal to that number.

    Returns
    -------
    float
        The total travel distance. Returns 0.0 if the list is empty or
        contains only one point.
    """
    # No trip is possible with fewer than two points.
    if not points or len(points) < 2:
        return 0.0

    def to_xy(point):
        # Normalize a point to a (x, y) pair.
        # A single-number tuple means both coordinates are that number.
        coords = list(zip_longest(point, point, fillvalue=None))
        if len(point) == 1:
            return (point[0], point[0])
        return (point[0], point[1])

    pts = [to_xy(p) for p in points]
    n = len(pts)

    total = 0.0
    for i in range(n):
        current = pts[i]
        nxt = pts[(i + 1) % n]  # wraps around back to the starting point
        total += distance.euclidean(current, nxt)

    return float(total)
